import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] v = new long[n];
        for (int i = 0; i < n; i++) v[i] = nextLong();
        int k = (int) nextLong();
        Arrays.sort(v, 0, k);        // first K ascending
        Arrays.sort(v, k, n);        // the rest ascending, printed in reverse
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < k; i++) out.append(i > 0 ? " " : "").append(v[i]);
        for (int i = n - 1; i >= k; i--) out.append(out.length() > 0 ? " " : "").append(v[i]);
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"os"
	"slices"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int64 {
		sc.Scan()
		v, _ := strconv.ParseInt(sc.Text(), 10, 64)
		return v
	}
	n := int(next())
	v := make([]int64, n)
	for i := range v {
		v[i] = next()
	}
	k := int(next())
	slices.Sort(v[:k]) // first K ascending
	slices.Sort(v[k:])
	slices.Reverse(v[k:]) // the rest descending
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	for i, x := range v {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(x, 10))
	}
	w.WriteByte('\n')
}
